const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_screen

async function ui_screen (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject
  }

  const { io, _ } = net(id)
  io.on = { up: (msg) => console.log('ui_screen:', msg.type) }
  if (invite) io.accept(invite)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })
  
  shadow.innerHTML = `
  <div class="ui-screen-canvas">
    <div class="grid-layer">
      <div class="cell"></div>
      <div class="cell"></div>
      <div class="cell"></div>
      <div class="cell"></div>
      <div class="cell"></div>
      <div class="cell"></div>
    </div>
    <div class="bottom-bar"></div>
  </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  await sdb.watch(onbatch)

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(p => drive.get(p).then(f => f.raw)))
      const func = on[type] || (() => {})
      func({ data })
    }
  }

  function inject ({ data }) { sheet.replaceSync(data[0]) }
}

function fallback_module () {
  return {
    api: () => ({
      _: { net_helper: { 0: '' } },
      drive: {
        'style/ui_screen.css': {
          raw: `
            :host { 
              display: block; 
              width: 100%; 
              max-width: 100%;
              aspect-ratio: 16 / 7; 
              overflow: hidden;
              box-sizing: border-box;
            }
            
            .ui-screen-canvas {
              background-color: #0d0d0d;
              width: 100%;
              height: 100%;
              display: flex;
              flex-direction: column;
              position: relative;
              box-sizing: border-box;
              border-radius: 8px; /* Slight roundness to look like a hardware screen */
            }

            .grid-layer {
              display: grid;
              grid-template-columns: repeat(3, 1fr);
              grid-template-rows: repeat(2, 1fr);
              gap: 1.5%;
              padding: 2%;
              flex: 1;
              box-sizing: border-box;
            }

            .cell {
              background-color: #141414;
              border-radius: 12px;
              box-shadow: inset 0 0 10px rgba(0,0,0,0.5);
            }

            .bottom-bar {
              height: 10%;
              min-height: 40px;
              background-color: #1a1a1a;
            }
          `
        }
      }
    }),
    _: { net_helper: {$:''} }
  }
}